+package com.example.contact;
+
+import java.util.ArrayList;
+import java.util.List;
+
+import org.springframework.stereotype.Service;
+
+/** Keeps submitted messages available while the application is running. */
+@Service
+public class ContactMessageStore {
+
+    private final List<ContactMessage> messages = new ArrayList<>();
+
+    public synchronized void add(ContactMessage message) {
+        messages.add(0, message);
+    }
+
+    public synchronized List<ContactMessage> getMessages() {
+        return List.copyOf(messages);
+    }
+
+    synchronized void clear() {
+        messages.clear();
+    }
+}
diff --git a/src/main/java/com/example/contact/ContactView.java b/src/main/java/com/example/contact/ContactView.java
