@@ -0,0 +1,108 @@
+package com.example.contact;
+
+import static org.junit.jupiter.api.Assertions.assertEquals;
+import static org.junit.jupiter.api.Assertions.assertFalse;
+import static org.junit.jupiter.api.Assertions.assertInstanceOf;
+import static org.junit.jupiter.api.Assertions.assertTrue;
+
+import org.junit.jupiter.api.BeforeEach;
+import org.junit.jupiter.api.Test;
+import org.springframework.beans.factory.annotation.Autowired;
+import org.springframework.boot.test.context.SpringBootTest;
+
+import com.vaadin.browserless.SpringBrowserlessTest;
+import com.vaadin.flow.component.Key;
+import com.vaadin.flow.component.button.Button;
+import com.vaadin.flow.component.dialog.Dialog;
+import com.vaadin.flow.component.grid.Grid;
+import com.vaadin.flow.component.html.H1;
+import com.vaadin.flow.component.notification.Notification;
+import com.vaadin.flow.component.textfield.EmailField;
+import com.vaadin.flow.component.textfield.TextArea;
+import com.vaadin.flow.component.textfield.TextField;
+import com.vaadin.flow.router.RouterLink;
+
+@SpringBootTest
+class ContactViewBrowserlessTest extends SpringBrowserlessTest {
+
+    @Autowired
+    private ContactMessageStore messageStore;
+
+    @BeforeEach
+    void clearMessages() {
+        messageStore.clear();
+    }
+
+    @Test
+    void emptySubmissionMarksTheRelevantFields() {
+        navigate(ContactView.class);
+
+        test($(Button.class).withText("Send").single()).click();
+
+        TextField name = $(TextField.class).withLabel("Name").single();
+        EmailField email = $(EmailField.class).withLabel("Email").single();
+        TextArea message = $(TextArea.class).withLabel("Message").single();
+        assertTrue(name.isInvalid());
+        assertEquals("Name is required", name.getErrorMessage());
+        assertTrue(email.isInvalid());
+        assertEquals("Give an e-mail address or a phone number", email.getErrorMessage());
+        assertTrue(message.isInvalid());
+        assertEquals("Message is required", message.getErrorMessage());
+        assertTrue($(Grid.class).exists());
+        assertEquals(0, test($(Grid.class).single()).size());
+    }
+
+    @Test
+    void validSubmissionResetsAndDisablesUntilTheNextEdit() {
+        navigate(ContactView.class);
+
+        test($(TextField.class).withLabel("Name").single()).setValue("Ada");
+        test($(EmailField.class).withLabel("Email").single()).setValue("ada@example.com");
+        test($(TextArea.class).withLabel("Message").single()).setValue("Hello");
+        Button send = $(Button.class).withText("Send").single();
+        fireShortcut(Key.ENTER);
+
+        assertFalse(send.isEnabled());
+        assertEquals("", $(TextField.class).withLabel("Name").single().getValue());
+        assertEquals("", $(EmailField.class).withLabel("Email").single().getValue());
+        assertEquals("", $(TextField.class).withLabel("Phone").single().getValue());
+        assertEquals("", $(TextArea.class).withLabel("Message").single().getValue());
+        assertEquals("Ada", test($(Grid.class).single()).getCellText(0, 0));
+        assertEquals("Hello", test($(Grid.class).single()).getCellText(0, 1));
+        assertTrue($(Notification.class).exists());
+        assertTrue($(Notification.class).all().stream()
+                .anyMatch(notification -> notification.getElement().getProperty("text").contains("Message sent")));
+
+        test($(TextField.class).withLabel("Phone").single()).setValue("555-0100");
+        assertTrue(send.isEnabled());
+    }
+
+    @Test
+    void leavingWithDraftRequiresAChoice() {
+        navigate(ContactView.class);
+        test($(TextField.class).withLabel("Name").single()).setValue("Draft");
+
+        test($(RouterLink.class).withText("About").single()).click();
+        Dialog dialog = $(Dialog.class).single();
+        assertTrue(dialog.isOpened());
+        assertInstanceOf(ContactView.class, getCurrentView());
+
+        test($(Button.class).withText("Keep editing").single()).click();
+        assertFalse(dialog.isOpened());
+        assertInstanceOf(ContactView.class, getCurrentView());
+
+        test($(RouterLink.class).withText("About").single()).click();
+        test($(Button.class).withText("Discard").single()).click();
+        assertInstanceOf(AboutView.class, getCurrentView());
+    }
+
+    @Test
+    void emptyFormLeavesWithoutAConfirmation() {
+        navigate(ContactView.class);
+
+        test($(RouterLink.class).withText("About").single()).click();
+
+        assertFalse($(Dialog.class).exists());
+        assertInstanceOf(AboutView.class, getCurrentView());
+    }
+}
